import math

def test_two_tokens():
    assert abs(solution.sequence_log_prob([0.5, 0.25]) - math.log(0.125)) < 1e-12

def test_certain_tokens():
    assert solution.sequence_log_prob([1.0, 1.0]) == 0.0

def test_three_tokens():
    want = math.log(0.9) + math.log(0.8) + math.log(0.5)
    assert abs(solution.sequence_log_prob([0.9, 0.8, 0.5]) - want) < 1e-12

def test_bad_probability_raises():
    for probs in ([0.5, 0.0], [0.5, 1.2], [-0.1]):
        try:
            solution.sequence_log_prob(probs)
        except ValueError:
            continue
        raise AssertionError("expected ValueError for %r" % (probs,))

def test_empty_raises():
    try:
        solution.sequence_log_prob([])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_mutation():
    probs = [0.5, 0.25]
    solution.sequence_log_prob(probs)
    assert probs == [0.5, 0.25]
